using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements.</summary>
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        ref float start = ref MemoryMarshal.GetReference(values);
        int length = values.Length;
        int i = 0;

        // Use 256-bit SIMD (8 floats) with multiple accumulators to hide latency
        if (Vector256.IsHardwareAccelerated && length >= Vector256<float>.Count * 4)
        {
            var acc0 = Vector256<float>.One;
            var acc1 = Vector256<float>.One;
            var acc2 = Vector256<float>.One;
            var acc3 = Vector256<float>.One;

            int limit = length - (Vector256<float>.Count * 4 - 1);
            int stride = Vector256<float>.Count;

            for (; i < limit; i += stride * 4)
            {
                acc0 *= Vector256.LoadUnsafe(ref start, (nuint)i);
                acc1 *= Vector256.LoadUnsafe(ref start, (nuint)(i + stride));
                acc2 *= Vector256.LoadUnsafe(ref start, (nuint)(i + stride * 2));
                acc3 *= Vector256.LoadUnsafe(ref start, (nuint)(i + stride * 3));
            }

            // Combine accumulators
            acc0 = acc0 * acc1 * acc2 * acc3;

            // Horizontal product of the vector
            float product = HorizontalProduct256(acc0);

            // Scalar tail
            for (; i < length; i++)
                product *= Unsafe.Add(ref start, i);

            return product;
        }

        if (Vector128.IsHardwareAccelerated && length >= Vector128<float>.Count * 4)
        {
            var acc0 = Vector128<float>.One;
            var acc1 = Vector128<float>.One;
            var acc2 = Vector128<float>.One;
            var acc3 = Vector128<float>.One;

            int limit = length - (Vector128<float>.Count * 4 - 1);
            int stride = Vector128<float>.Count;

            for (; i < limit; i += stride * 4)
            {
                acc0 *= Vector128.LoadUnsafe(ref start, (nuint)i);
                acc1 *= Vector128.LoadUnsafe(ref start, (nuint)(i + stride));
                acc2 *= Vector128.LoadUnsafe(ref start, (nuint)(i + stride * 2));
                acc3 *= Vector128.LoadUnsafe(ref start, (nuint)(i + stride * 3));
            }

            acc0 = acc0 * acc1 * acc2 * acc3;
            float product = HorizontalProduct128(acc0);

            for (; i < length; i++)
                product *= Unsafe.Add(ref start, i);

            return product;
        }

        // Scalar fallback with 4x unrolling
        {
            float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
            int limit = length - 3;
            for (; i < limit; i += 4)
            {
                p0 *= Unsafe.Add(ref start, i);
                p1 *= Unsafe.Add(ref start, i + 1);
                p2 *= Unsafe.Add(ref start, i + 2);
                p3 *= Unsafe.Add(ref start, i + 3);
            }
            float product = p0 * p1 * p2 * p3;
            for (; i < length; i++)
                product *= Unsafe.Add(ref start, i);
            return product;
        }
    }

    private static float HorizontalProduct256(Vector256<float> v)
    {
        var lo = v.GetLower();
        var hi = v.GetUpper();
        return HorizontalProduct128(lo * hi);
    }

    private static float HorizontalProduct128(Vector128<float> v)
    {
        // [a, b, c, d] -> product of all 4
        var shuffled = Vector128.Shuffle(v, Vector128.Create(2, 3, 0, 1)); // [c, d, a, b]
        v *= shuffled; // [ac, bd, ac, bd]
        shuffled = Vector128.Shuffle(v, Vector128.Create(1, 0, 3, 2)); // [bd, ac, bd, ac]
        v *= shuffled; // [abcd, abcd, abcd, abcd]
        return v.ToScalar();
    }
}

